<?php
require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php';
if($_SERVER['REQUEST_METHOD']==='POST'){
    $items=json_decode($_POST['items']??'[]',true);$customer=(int)($_POST['customer_id']??0) ?: null;$discount=(float)($_POST['discount']??0);$tax=(float)($_POST['tax']??0);$payment=$_POST['payment_method']??'cash';$received=(float)($_POST['received']??0);
    if(!$items){flash('danger','Cart is empty.');header("Location:pos.php");exit;}
    try{$pdo->beginTransaction();
        $subtotal=0;$clean=[];
        foreach($items as $it){$st=$pdo->prepare("SELECT * FROM products WHERE id=? FOR UPDATE");$st->execute([(int)$it['id']]);$p=$st->fetch();$qty=(int)$it['qty'];if(!$p||$qty<1||$p['stock_qty']<$qty)throw new Exception("Insufficient stock for ".($p['name']??'product'));$line=$p['selling_price']*$qty;$subtotal+=$line;$clean[]=['p'=>$p,'qty'=>$qty,'line'=>$line];}
        $total=max(0,$subtotal-$discount+$tax);$invoice='INV-'.date('Ymd').'-'.str_pad((string)(rand(1,9999)),4,'0',STR_PAD_LEFT);
        $st=$pdo->prepare("INSERT INTO sales(invoice_no,customer_id,user_id,subtotal,discount,tax,total,payment_method,amount_received,status) VALUES(?,?,?,?,?,?,?,?,?,'completed')");
        $st->execute([$invoice,$customer,$_SESSION['user']['id'],$subtotal,$discount,$tax,$total,$payment,$received]);
        $saleId=$pdo->lastInsertId();
        foreach($clean as $x){$p=$x['p'];$pdo->prepare("INSERT INTO sale_items(sale_id,product_id,quantity,unit_price,cost_price,total) VALUES(?,?,?,?,?,?)")->execute([$saleId,$p['id'],$x['qty'],$p['selling_price'],$p['purchase_price'],$x['line']]);$pdo->prepare("UPDATE products SET stock_qty=stock_qty-? WHERE id=?")->execute([$x['qty'],$p['id']]);$pdo->prepare("INSERT INTO stock_movements(product_id,type,quantity,reference,note,user_id) VALUES(?,'out',?,?,?,?)")->execute([$p['id'],$x['qty'],$invoice,'POS sale',$_SESSION['user']['id'] ?? $_SESSION['user']['id']]);}
        $pdo->commit();header("Location:view.php?id=".$saleId);exit;
    }catch(Exception $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger',$e->getMessage());header("Location:pos.php");exit;}
}
$products=$pdo->query("SELECT id,name,sku,selling_price,stock_qty FROM products WHERE stock_qty>0 ORDER BY name")->fetchAll();$customers=$pdo->query("SELECT id,name FROM customers ORDER BY name")->fetchAll();$page_title='POS';require __DIR__.'/../partials/header.php';?>
<div class="d-flex justify-content-between align-items-center mb-3"><div><h3 class="fw-bold">Point of Sale</h3><p class="text-muted mb-0">Create a new sale.</p></div></div>
<form method="post" id="posForm"><input type="hidden" name="items" id="items"><div class="row g-3"><div class="col-lg-8"><div class="card p-3"><div class="row g-2 mb-3"><div class="col-md-8"><input id="productSearch" class="form-control" placeholder="Search products..."></div></div><div class="row g-2" id="productGrid"><?php foreach($products as $p):?><div class="col-6 col-md-4 col-xl-3 product-card" data-name="<?=e(strtolower($p['name'].' '.$p['sku']))?>"><div class="card pos-product h-100 p-3" onclick='addItem(<?=e(json_encode($p, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP))?>)'><div class="fw-semibold"><?=e($p['name'])?></div><small class="text-muted"><?=e($p['sku'])?></small><div class="mt-2 fw-bold">$<?=money($p['selling_price'])?></div><small>Stock: <?=$p['stock_qty']?></small></div></div><?php endforeach;?></div></div></div>
<div class="col-lg-4"><div class="card p-3 cart-box"><h5 class="fw-bold">Cart</h5><div id="cart"></div><hr><select name="customer_id" class="form-select mb-2"><option value="">Walk-in Customer</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select><div class="row g-2"><div class="col-6"><label class="small">Discount</label><input id="discount" name="discount" type="number" step=".01" value="0" class="form-control"></div><div class="col-6"><label class="small">Tax</label><input id="tax" name="tax" type="number" step=".01" value="0" class="form-control"></div></div><select name="payment_method" class="form-select my-2"><option value="cash">Cash</option><option value="card">Card</option><option value="bank">Bank Transfer</option><option value="mobile">Mobile Money</option></select><input name="received" type="number" step=".01" value="0" class="form-control mb-2" placeholder="Amount received"><div class="d-flex justify-content-between fs-5"><strong>Total</strong><strong id="total">$0.00</strong></div><button class="btn btn-primary w-100 mt-3" onclick="return submitPOS()">Complete Sale</button></div></div></div></form>
<script>
let cart=[];
function addItem(p){let x=cart.find(i=>i.id==p.id);if(x)x.qty++;else cart.push({id:+p.id,name:p.name,price:+p.selling_price,qty:1,max:+p.stock_qty});render();}
function changeQty(id,v){let x=cart.find(i=>i.id==id);if(x){x.qty=Math.max(1,Math.min(x.max,+v||1));render();}}
function removeItem(id){cart=cart.filter(i=>i.id!=id);render();}
function render(){let box=document.getElementById('cart');box.innerHTML=cart.length?cart.map(i=>`<div class="d-flex gap-2 align-items-center border-bottom py-2"><div class="flex-grow-1"><div class="small fw-semibold">${i.name}</div><input class="form-control form-control-sm mt-1" type="number" min="1" max="${i.max}" value="${i.qty}" onchange="changeQty(${i.id},this.value)"></div><div>$${(i.price*i.qty).toFixed(2)}</div><button type="button" class="btn btn-sm btn-link text-danger" onclick="removeItem(${i.id})">×</button></div>`).join(''):'<div class="text-muted py-4 text-center">No items</div>';let sub=cart.reduce((a,i)=>a+i.price*i.qty,0),d=+document.getElementById('discount').value||0,t=+document.getElementById('tax').value||0;document.getElementById('total').textContent='$'+Math.max(0,sub-d+t).toFixed(2);}
function submitPOS(){if(!cart.length){alert('Add at least one product.');return false;}document.getElementById('items').value=JSON.stringify(cart.map(i=>({id:i.id,qty:i.qty})));return true;}
document.getElementById('discount').addEventListener('input',render);document.getElementById('tax').addEventListener('input',render);document.getElementById('productSearch').addEventListener('input',e=>document.querySelectorAll('.product-card').forEach(x=>x.style.display=x.dataset.name.includes(e.target.value.toLowerCase())?'':'none'));render();
</script>
<?php require __DIR__.'/../partials/footer.php';?>
